    <style>
        :root{--a:#00ff9d;--p:#b026ff;--b:#2575fc}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#fff;font-family:Roboto,sans-serif;background:url('{{ asset("Imagenes/Pantalla_Inicio.jpg") }}') center/cover fixed no-repeat}body:before{content:'';position:fixed;inset:0;background:rgba(0,0,0,.75);z-index:-1}.navbar-custom{background:rgba(0,0,0,.86);border-bottom:3px solid var(--a)}.game-title{color:var(--a);font:1.15rem 'Press Start 2P',cursive}.btn-home,.player-name{color:#fff;border:2px solid #fff;border-radius:999px;padding:.5rem 1rem;text-decoration:none;background:rgba(255,255,255,.08)}.challenge-container{max-width:1400px;margin:2rem auto;padding:1.5rem;border-left:5px solid var(--p);border-radius:18px;background:rgba(0,0,0,.8)}.challenge-header{border-bottom:2px solid var(--p);padding-bottom:1rem}.challenge-title{color:var(--a);font:1.2rem 'Press Start 2P',cursive}.badge-level{background:var(--p);padding:.4rem .75rem;border-radius:8px}.hint-box{padding:1rem;margin:1rem 0;border-left:4px solid #ffcc00;border-radius:0 10px 10px 0;background:rgba(255,204,0,.13)}.reference-card{padding:1rem;border:2px solid rgba(0,255,157,.45);border-radius:16px;background:rgba(15,23,42,.8)}.reference-flow{display:flex;gap:1rem;align-items:center;justify-content:center;flex-wrap:wrap}.screen{width:220px;min-height:125px;padding:1rem;border-radius:12px;background:#17243d;border:1px solid #5772a5}.screen strong{color:#9fffd5}.arrow{font-size:1.8rem;color:var(--a)}.objectives-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:.65rem;padding:0;list-style:none}.objectives-list li{padding:.75rem;border-radius:12px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16)}.objectives-list i{color:var(--a);margin-right:.35rem}.editor-tabs{display:flex;gap:.5rem;margin-top:1.2rem}.editor-tab{border:1px solid rgba(0,255,157,.5);border-radius:10px 10px 0 0;padding:.65rem 1rem;background:#111a30;color:#fff}.editor-tab.active{background:var(--a);color:#06111c}.editor-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.editor-panel,.preview-panel{min-height:500px;border-radius:12px;overflow:hidden}.CodeMirror{height:500px!important;border:3px solid var(--a);border-radius:12px;font-size:13px}.preview-panel{background:#fff;border:3px solid var(--a)}.preview-panel iframe{width:100%;height:100%;min-height:494px;border:0;background:#fff}.validation-panel{margin-top:1rem;padding:1rem;border-radius:14px;background:rgba(15,23,42,.92);border:1px solid rgba(255,255,255,.16)}.validation-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.5rem}.validation-item{padding:.55rem .7rem;border-radius:10px;background:rgba(255,255,255,.08)}.validation-item.ok{color:#86efac}.validation-item.missing{color:#fca5a5}.action-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:.75rem;margin:1.2rem 0;padding:.85rem;border:2px solid rgba(0,255,157,.5);border-radius:16px;background:rgba(2,6,23,.94)}.btn-run,.btn-submit{border:0;border-radius:999px;padding:.75rem 1.35rem;font-weight:700}.btn-run{color:#fff;background:linear-gradient(45deg,#6a11cb,var(--b))}.btn-submit{color:#07131f;background:linear-gradient(45deg,#16a34a,var(--a))}.feedback{display:none;margin-top:1rem;padding:1rem;border-radius:10px}.feedback.show{display:block}.feedback.success{background:rgba(40,167,69,.2);border-left:4px solid #28a745}.feedback.error{background:rgba(220,53,69,.2);border-left:4px solid #dc3545}@media(max-width:850px){.editor-grid{grid-template-columns:1fr}.game-title{font-size:.8rem}}
