<body>
<nav class="navbar navbar-custom py-3"><div class="container-fluid d-flex align-items-center justify-content-between gap-2"><a class="btn-home" href="{{ route('alumno.desafios.programacion') }}"><i class="fas fa-arrow-left me-2"></i>Volver</a><div class="game-title">CODEPLAY</div><div class="player-name"><i class="fas fa-user me-2"></i>{{ session('usuario_nombre','Jugador') }}</div></div></nav>
<main class="container-fluid px-3 px-lg-5"><section class="challenge-container">
<header class="challenge-header"><h1 class="challenge-title">Desafío 19: Tienda Online Básica</h1><p class="text-white-50 mb-2">Construye una pequeña tienda con catálogo, carrito y checkout simulado.</p><span class="badge-level">NIVEL 19 · MAESTRO 4★ +</span><span class="badge bg-success ms-2">500 puntos</span></header>
<div class="hint-box"><strong>Proyecto en dos pantallas:</strong> escribe la vista de productos en el primer editor y la pantalla de pago en el segundo. No hay pagos reales: el carrito se guarda solo en <code>sessionStorage</code> y se borra al cerrar la pestaña.</div>
<div class="reference-card"><h2 class="h5" style="color:var(--a)"><i class="fas fa-route me-2"></i>Flujo esperado</h2><div class="reference-flow"><div class="screen"><strong>Catálogo</strong><br><small>Productos + botón Agregar + carrito</small></div><div class="arrow">→</div><div class="screen"><strong>Checkout</strong><br><small>Resumen + datos + pago simulado</small></div></div></div>
<h2 class="h4 mt-4"><i class="fas fa-bullseye me-2"></i>Objetivos del proyecto</h2><ul class="objectives-list mt-3"><li><i class="fas fa-circle-check"></i>Crea una pantalla de <strong>productos</strong> con al menos dos tarjetas.</li><li><i class="fas fa-circle-check"></i>Incluye un botón de carrito que lleve a la pantalla <strong>checkout</strong>.</li><li><i class="fas fa-circle-check"></i>Construye una segunda vista con resumen y formulario de pago simulado.</li><li><i class="fas fa-circle-check"></i>Guarda y lee el carrito con <code>sessionStorage</code> o <code>localStorage</code>.</li><li><i class="fas fa-circle-check"></i>Usa eventos, botones y <code>textContent</code> para actualizar la interfaz.</li><li><i class="fas fa-circle-check"></i>Aplica Grid o Flexbox, fondos y bordes redondeados.</li></ul>
<div class="editor-tabs"><button class="editor-tab active" data-editor="products">1 · Productos</button><button class="editor-tab" data-editor="checkout">2 · Checkout</button></div><div class="editor-grid"><div id="productsPanel" class="editor-panel"><textarea id="productsEditor"><!DOCTYPE html>
<section id="productos" class="catalogo"><h1>Mi tienda</h1><div class="producto card"><h2>Mochila</h2><p>$25</p><button class="agregar" data-producto="Mochila" data-precio="25">Agregar</button></div><div class="producto card"><h2>Audífonos</h2><p>$40</p><button class="agregar" data-producto="Audífonos" data-precio="40">Agregar</button></div><button id="carrito">🛒 Ver carrito</button></section><style>.catalogo{display:grid;gap:16px;background:#eaf2ff;border-radius:16px;padding:24px}.card{background:white;border-radius:12px;padding:18px}</style><script>const carrito=[];document.querySelectorAll('.agregar').forEach(b=>b.addEventListener('click',()=>{carrito.push(b.dataset.producto);sessionStorage.setItem('carrito',JSON.stringify(carrito));}));document.getElementById('carrito').addEventListener('click',()=>{location.hash='checkout';});</script></textarea><textarea id="checkoutEditor"><section id="checkout" class="checkout"><h1>Pago simulado</h1><div id="resumen"></div><form id="pago"><input name="nombre" placeholder="Nombre" required><button type="submit">Confirmar pedido</button></form><p id="mensaje"></p></section><script>const productos=JSON.parse(sessionStorage.getItem('carrito')||'[]');document.getElementById('resumen').textContent=productos.join(', ')||'Carrito vacío';document.getElementById('pago').addEventListener('submit',e=>{e.preventDefault();document.getElementById('mensaje').textContent='Pedido simulado correctamente';});</script></textarea></div><div class="preview-panel"><iframe id="previewFrame" title="Vista previa de la tienda" sandbox="allow-scripts allow-forms allow-modals"></iframe></div></div>
<section class="validation-panel"><h2 class="h5"><i class="fas fa-list-check me-2"></i>Progreso del desafío</h2><div id="validationGrid" class="validation-grid"></div></section><div class="action-toolbar"><button id="runButton" class="btn-run"><i class="fas fa-play me-2"></i>Ejecutar tienda</button><button id="submitButton" class="btn-submit"><i class="fas fa-check me-2"></i>Entregar solución</button><span class="text-white-50">Completa las dos pantallas antes de entregar.</span></div><div id="feedback" class="feedback"></div>
</section></main>
<script>
const productsEditor=CodeMirror.fromTextArea(document.getElementById('productsEditor'),{mode:'htmlmixed',theme:'dracula',lineNumbers:true,lineWrapping:true});const checkoutEditor=CodeMirror.fromTextArea(document.getElementById('checkoutEditor'),{mode:'htmlmixed',theme:'dracula',lineNumbers:true,lineWrapping:true});const productWrapper=productsEditor.getWrapperElement(),checkoutWrapper=checkoutEditor.getWrapperElement();const previewFrame=document.getElementById('previewFrame'),grid=document.getElementById('validationGrid'),feedback=document.getElementById('feedback');const labels={catalog:'Catálogo y productos',cards:'Dos tarjetas',checkout:'Pantalla de checkout',storage:'Carrito temporal',navigation:'Conexión entre vistas',events:'Eventos y botones',style:'Estilo visual'};
function code(){return productsEditor.getValue()+'\n'+checkoutEditor.getValue()}function evaluateCode(c){const l=c.toLowerCase(),compact=l.replace(/\s+/g,'');const cards=(c.match(/class\s*=\s*["'][^"']*\b(producto|product|card)\b[^"']*["']/gi)||[]).length;return{catalog:l.includes('productos')||l.includes('catalogo')||l.includes('catalog'),cards:cards>=2,checkout:l.includes('checkout')||l.includes('pago')||l.includes('carrito'),storage:(l.includes('sessionstorage')||l.includes('localstorage'))&&l.includes('setitem')&&l.includes('getitem'),navigation:l.includes('href="#checkout"')||l.includes("href='#checkout'")||l.includes('showcheckout')||l.includes('checkoutview')||l.includes("location.hash='checkout'")||l.includes('location.hash="checkout"'),events:l.includes('<button')&&l.includes('addeventlistener')&&l.includes('textcontent'),style:(compact.includes('display:grid')||compact.includes('display:flex'))&&(l.includes('background:')||l.includes('background-color'))&&l.includes('border-radius')}}
const baseEvaluateCode=evaluateCode;evaluateCode=function(c){const checks=baseEvaluateCode(c);if(c.toLowerCase().includes('location.hash'))checks.navigation=true;return checks};
function prepareStarter(){let products=productsEditor.getValue();products=products.replace(/<div class="producto card"><h2>Audífonos[\s\S]*?<\/div>/,'').replace("sessionStorage.setItem('carrito',JSON.stringify(carrito));",'').replace("document.getElementById('carrito').addEventListener('click',()=>{location.hash='checkout';});",'');productsEditor.setValue(products);let checkout=checkoutEditor.getValue();checkout=checkout.replace("const productos=JSON.parse(sessionStorage.getItem('carrito')||'[]');",'const productos=[];').replace("document.getElementById('resumen').textContent=productos.join(', ')||'Carrito vacío';", "document.getElementById('resumen').textContent='Agrega productos al carrito';");checkoutEditor.setValue(checkout)}
function render(show=false){const checks=evaluateCode(code());grid.innerHTML=Object.entries(checks).map(([k,v])=>`<div class="validation-item ${v?'ok':'missing'}"><i class="fas ${v?'fa-check':'fa-circle'} me-2"></i>${labels[k]}</div>`).join('');if(show&&!Object.values(checks).every(Boolean)){feedback.className='feedback error show';feedback.textContent=`Aún faltan objetivos (${Object.values(checks).filter(Boolean).length}/${Object.keys(checks).length}).`;}return Object.values(checks).every(Boolean)}
function run(){const p=productsEditor.getValue(),c=checkoutEditor.getValue();previewFrame.srcdoc=`<div id="app">${p}${c}</div><script>const sincronizarPantallas=()=>{const productos=document.getElementById('productos'),checkout=document.getElementById('checkout');if(!productos||!checkout)return;const mostrarCheckout=location.hash==='#checkout';productos.hidden=mostrarCheckout;checkout.hidden=!mostrarCheckout};window.addEventListener('hashchange',sincronizarPantallas);sincronizarPantallas();<\/script>`;render(false)}async function submit(){run();if(!render(true))return;try{const r=await fetch('{{ route("desafios.procesar-recompensa") }}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({nivel:19,codigo:code()})});const d=await r.json();if(!r.ok||!d.success){feedback.className='feedback error show';feedback.textContent=d.message||d.error||'No se pudo validar la solución.';return}feedback.className='feedback success show';feedback.textContent=`¡Desafío completado! Ganaste ${d.puntos_otorgados} puntos.`;if(typeof confetti==='function')confetti({particleCount:180,spread:90})}catch(e){feedback.className='feedback error show';feedback.textContent='No se pudo registrar la recompensa.'}}
document.querySelectorAll('.editor-tab').forEach(t=>t.addEventListener('click',()=>{document.querySelectorAll('.editor-tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');const show=t.dataset.editor==='products';productWrapper.style.display=show?'block':'none';checkoutWrapper.style.display=show?'none':'block';productsEditor.refresh();checkoutEditor.refresh()}));document.getElementById('runButton').addEventListener('click',run);document.getElementById('submitButton').addEventListener('click',submit);window.addEventListener('load',()=>{prepareStarter();productWrapper.style.display='block';checkoutWrapper.style.display='none';run();const info=@json($infoRecompensa);if(info.ya_completado&&!info.puede_reclamar){feedback.className='feedback show';feedback.textContent=`Ya completaste este desafío. Podrás reclamar nuevamente ${info.tiempo_restante}.`}});
</script></body></html>
